// for: biết trước số lần lặp
for (let i = 1; i <= 3; i++) {
  console.log("Lần", i);
}

// while: lặp khi điều kiện còn đúng
let n = 3;
while (n > 0) {
  console.log("Đếm ngược:", n);
  n--;
}

// for...of: duyệt từng phần tử của mảng
for (const fruit of ["táo", "cam", "xoài"]) {
  console.log(fruit);
}

